<?php
class BookingRepository
{
    public function __construct(private PDO $db) {}
    public function slotTaken(string $date,string $time,?int $ignoreId=null): bool {
        $sql="SELECT booking_id FROM bookings WHERE booking_date=? AND booking_time=? AND status IN ('Pending','Confirmed')"; $args=[$date,$time]; if($ignoreId){$sql.=' AND booking_id <> ?';$args[]=$ignoreId;} $s=$this->db->prepare($sql);$s->execute($args);return(bool)$s->fetch();
    }
    public function create(Booking $b): bool { $s=$this->db->prepare('INSERT INTO bookings(customer_id,vehicle_id,service_id,booking_date,booking_time,status,notes) VALUES(?,?,?,?,?,?,?)'); return $s->execute([$b->customerId(),$b->vehicleId(),$b->serviceId(),$b->date(),$b->time(),$b->status(),$b->notes()]); }
    public function cancel(int $id,int $customerId): bool { $s=$this->db->prepare("UPDATE bookings SET status='Canceled' WHERE booking_id=? AND customer_id=? AND status IN ('Pending','Confirmed')");$s->execute([$id,$customerId]);return$s->rowCount()>0; }
    public function findForCustomer(int $id): array { $s=$this->db->prepare("SELECT b.*,v.registration_number,v.make,v.model,s.service_name,s.price,m.full_name mechanic_name FROM bookings b JOIN vehicles v ON b.vehicle_id=v.vehicle_id JOIN services s ON b.service_id=s.service_id LEFT JOIN users m ON b.mechanic_id=m.user_id WHERE b.customer_id=? ORDER BY b.booking_date DESC,b.booking_time DESC");$s->execute([$id]);return$s->fetchAll(); }
    public function findAll(): array { return $this->db->query("SELECT b.*,c.full_name customer_name,v.registration_number,v.make,v.model,s.service_name,m.full_name mechanic_name FROM bookings b JOIN users c ON b.customer_id=c.user_id JOIN vehicles v ON b.vehicle_id=v.vehicle_id JOIN services s ON b.service_id=s.service_id LEFT JOIN users m ON b.mechanic_id=m.user_id ORDER BY b.booking_date DESC,b.booking_time DESC")->fetchAll(); }
    public function find(int $id): ?array { $s=$this->db->prepare("SELECT b.*,c.full_name customer_name,v.registration_number,v.make,v.model,s.service_name FROM bookings b JOIN users c ON b.customer_id=c.user_id JOIN vehicles v ON b.vehicle_id=v.vehicle_id JOIN services s ON b.service_id=s.service_id WHERE b.booking_id=?");$s->execute([$id]);return$s->fetch()?:null; }
    public function findForCustomerById(int $id,int $customerId): ?array { $s=$this->db->prepare('SELECT * FROM bookings WHERE booking_id=? AND customer_id=?');$s->execute([$id,$customerId]);return$s->fetch()?:null; }
    public function reschedule(int $id,int $customerId,string $date,string $time): bool { $s=$this->db->prepare("UPDATE bookings SET booking_date=?,booking_time=?,status='Pending' WHERE booking_id=? AND customer_id=? AND status <> 'Canceled'");$s->execute([$date,$time,$id,$customerId]);return$s->rowCount()>0; }
    public function assignMechanic(int $bookingId,int $mechanicId): bool { $s=$this->db->prepare("UPDATE bookings SET mechanic_id=?,status='Confirmed' WHERE booking_id=?");$s->execute([$mechanicId,$bookingId]);return$s->rowCount()>0; }
    public function forMechanic(int $id): array { $s=$this->db->prepare("SELECT b.*,c.full_name customer_name,v.registration_number,v.make,v.model,s.service_name,s.price FROM bookings b JOIN users c ON b.customer_id=c.user_id JOIN vehicles v ON b.vehicle_id=v.vehicle_id JOIN services s ON b.service_id=s.service_id WHERE b.mechanic_id=? ORDER BY b.booking_date,b.booking_time");$s->execute([$id]);return$s->fetchAll(); }
    public function counts(): array { $q=fn($sql)=>(int)$this->db->query($sql)->fetch()['total']; return ['customers'=>$q("SELECT COUNT(*) total FROM users WHERE role='customer'"),'mechanics'=>$q("SELECT COUNT(*) total FROM users WHERE role='mechanic'"),'vehicles'=>$q('SELECT COUNT(*) total FROM vehicles'),'bookings'=>$q('SELECT COUNT(*) total FROM bookings'),'pending'=>$q("SELECT COUNT(*) total FROM bookings WHERE status='Pending'"),'completed'=>$q("SELECT COUNT(*) total FROM bookings WHERE status='Completed'")]; }
    public function complete(int $id,int $mechanicId): bool { $s=$this->db->prepare("UPDATE bookings SET status='Completed' WHERE booking_id=? AND mechanic_id=?");$s->execute([$id,$mechanicId]);return$s->rowCount()>0;}
}
